patch.content:
/* Shop.mn-ийн загвар */

body {
  background-color: #f5f6f8;
  color: #18181b;
}

body {
  font-family: system-ui, "Segoe UI", sans-serif;
  line-height: 1.6;
}

h1 {
  font-size: 36px;
}
.product-card {
  background-color: #ffffff;
  padding: 16px;
  border-radius: 10px;
}
.btn-add {
  background-color: #2563eb;
  color: #ffffff;
  padding: 10px 16px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
}
/* энд бичнэ үү */

hints.code:
.product-grid {
  display: grid;
  grid-template-columns: /* хоёр багана */;
  /* gap-аа өөрөө нэм */
}
